def isPalindrome(s: str) -> bool:
    filtered = []
    for char in s:
        if ('a' <= char <= 'z') or ('A' <= char <= 'Z') or ('0' <= char <= '9'):
            filtered.append(char.lower())
    n = len(filtered)
    all_match = True
    for i in range(n):
        for j in range(n):
            if i + j == n - 1:
                if filtered[i] != filtered[j]:
                    all_match = False
    return all_match

